mapper.select:
SELECT pr.id, pr.paper_id AS paperId, gr.id AS globalId, pr.ref_index as refId, gr.title, gr.abstract AS abstractText, gr.linked_paper_id AS linkedPaperId, gr.citation_count AS citationCount, p.title AS sourcePaperTitle, 1 - (gr.embedding <=> cast(#{vectorStr} as vector)) AS score FROM paper_references pr INNER JOIN global_references gr ON pr.global_ref_id = gr.id LEFT JOIN papers p ON pr.paper_id = p.id WHERE gr.embedding IS NOT NULL
AND pr.paper_id = #{paperId}
ORDER BY gr.embedding <=> cast(#{vectorStr} as vector) LIMIT #{topK}
